#!/usr/bin/env bash
# Paste this entire block into:  ~/application/Hinter
set -euo pipefail
cd "$(dirname "$0" 2>/dev/null || pwd)"
# If already in Hinter root:
pwd

echo "Writing hinter-web-mobile.tar.gz ..."
base64 -d > hinter-web-mobile.tar.gz << 'B64'

B64

echo "Extracting apps/web and apps/mobile ..."
tar -xzf hinter-web-mobile.tar.gz
rm -f hinter-web-mobile.tar.gz
echo "Done. Files:"
find apps/web apps/mobile -type f | head -40
echo ""
echo "Next:"
echo "  cd apps/web && npm install && npm run dev"
echo "  cd apps/mobile && npm install && npx expo start"
